    s16 = sl(table([tr('Mạch', 'Circuit'), tr('Công thức', 'Formula')], [['Wien', 'fr = 1/(2πRC)'], [tr('Dịch pha', 'Phase-shift'), 'fr = 1/(2π√6RC) ; Rf = 29Ri'], ['Colpitts', 'fr = 1/(2π√(L·CT)) ; Av = C1/C2'], [tr('555 phi ổn', '555 astable'), 'f = 1.44/((R1+2R2)C)'], [tr('555 đơn ổn', '555 monostable'), 'tW = 1.1RC']]),
             K[4], tr('Bảng công thức chương 16', 'Chapter 16 formula table'), tr('Năm dòng này đủ cho phần tính toán của chương.', 'These five lines cover the calculations of the chapter.'))
    s17 = sl(ul([tr('Dao động = hồi tiếp dương với Av·B = 1, pha 0°', 'Oscillation = positive feedback with Av·B = 1 and 0° phase'), tr('RC cho tần số thấp, LC/thạch anh cho tần số cao/ổn định', 'RC for low frequencies, LC/crystal for high or stable ones'), tr('Module sau: ổn áp và IC ổn áp', 'Next module: voltage regulators and IC regulators')]),
             K[4], tr('Ba ý chính', 'Three take-aways'), tr('Hãy nhớ công thức riêng của từng họ.', 'Remember the formula of each family.'))
    P.append(dict(title=tr('Ứng dụng và tổng kết', 'Applications and summary'), bullets=[tr('Định thời (minh hoạ)', 'Timing (illustrative)'), tr('Bảng công thức', 'Formula table'), tr('Ba ý chính', 'Take-aways')], slides=[s15, s16, s17]))
    nt = '<h3>1. ' + tr('Nội dung chi tiết đối chiếu sách', 'Detailed content mapped to the books') + '</h3>' + ul([tr('Floyd §16–1 mạch dao động; §16–2 dao động hồi tiếp; §16–3 hồi tiếp RC (Wien, dịch pha, twin-T); §16–4 hồi tiếp LC và thạch anh; §16–5 dao động thư giãn; §16–6 IC 555 phi ổn; §16–7…16–8 đơn ổn và PWM.', 'Floyd §16–1 oscillators; §16–2 feedback oscillators; §16–3 RC feedback (Wien, phase-shift, twin-T); §16–4 LC feedback and crystals; §16–5 relaxation oscillators; §16–6 the 555 astable; §16–7…16–8 monostable and PWM.'), tr('Đọc thêm: Jaeger 5e Ch.12 §12.7, 12.9 theo bản đồ đề cương.', 'See also Jaeger 5e Ch.12 §12.7, 12.9 per the syllabus map.')])
    nt += '<h3>2. ' + tr('Năm ví dụ có lời giải số', 'Five worked examples') + '</h3>' + ''.join([ex('1', f'Wien fr = 1/(2π·6.2k·0.02μ) = {f(f6,0)} Hz'), ex('2', f'Phase-shift: Rf = 29·4.7k = 136 kΩ, fr = {f(f11,0)} Hz'), ex('3', 'Colpitts C1 = 470 pF, C2 = 47 pF → Av = 10'), ex('4', f'555 astable: f = 1.44/((1k+6.6k)·0.047μ) = {f(f20,0)} Hz'), ex('5', f'Cext for 25 kHz = {f(c21*1e6,4)} μF')])
    nt += '<h3>3. ' + tr('Bối cảnh lịch sử/lý thuyết', 'History and theory context') + '</h3><p>' + tr('Tiêu chuẩn Barkhausen (1921) mô tả điều kiện dao động; mạch cầu Wien dùng trong máy phát tín hiệu đầu tiên của Hewlett-Packard; IC 555 do Hans Camenzind thiết kế năm 1971.', 'The Barkhausen criterion (1921) states the oscillation condition; the Wien bridge powered Hewlett-Packard’s first signal generator; the 555 IC was designed by Hans Camenzind in 1971.') + '</p>'
    nt += '<h3>4. ' + tr('Ca ứng dụng trên tàu bay (minh hoạ)', 'Aircraft case study (illustrative)') + '</h3><p>' + tr('Minh hoạ: bộ dao động thạch anh làm nguồn xung nhịp cho thiết bị điện tử hàng không; 555 tạo xung PWM cho động cơ servo trong bài thực hành. Không mô tả hệ thống cụ thể.', 'Illustrative: a crystal oscillator as the clock source of avionics electronics; a 555 generating the PWM for the servomotor in the lab. Not a specific system.') + '</p>'
    nt += '<h3>5. ' + tr('Bẫy khi làm bài thi', 'Exam pitfalls') + '</h3>' + ul([tr('Nhầm độ lợi cầu Wien (3) với dịch pha (29).', 'Confusing the Wien-bridge gain (3) with the phase-shift gain (29).'), tr('Quên 1,44 (không phải 1,1) cho tần số phi ổn.', 'Using 1.1 instead of 1.44 for the astable frequency.'), tr('Quên chu kỳ làm việc = (R1+R2)/(R1+2R2).', 'Forgetting duty = (R1+R2)/(R1+2R2).'), tr('Nhầm “độ lợi vòng = 1” với “độ lợi mạch khuếch đại = 1”.', 'Mixing “loop gain = 1” with “amplifier gain = 1”.')])
    return dict(subtitle=tr('Điều kiện dao động, cầu Wien, dịch pha, Colpitts, dao động thư giãn và IC 555 (Floyd chương 16).', 'Oscillation conditions, Wien-bridge, phase-shift, Colpitts, relaxation oscillators and the 555 timer (Floyd Chapter 16).'), time=tr('≈ 6 giờ', '≈ 6 h'),
                objectives=[tr('Nêu hai điều kiện dao động', 'State the two oscillation conditions'), tr('Tính tần số và độ lợi cần có của dao động RC, LC', 'Compute frequency and required gain of RC and LC oscillators'), tr('Phân tích bộ phát tam giác/răng cưa', 'Analyse triangle and sawtooth generators'), tr('Thiết kế 555 phi ổn và đơn ổn', 'Design 555 astable and monostable circuits')], parts=P, notes=nt)
